    }
    register WDOGCONTROL size 4 @ 0x8 {
        // Watchdog control register. Controls the decrement step value and enables reset/interrupt generation. Writing to this register when locked (WDOGLOCK != 0x1ACCE551) is ignored. Writing INTEN=1 reloads counter from WDOGLOAD if it was previously disabled.
        param init_val = 0x0;
        field STEP_VALUE @ [4:2] {
            // Step value for the counter. Configures the clock division rate: 000=÷1, 001=÷2, 010=÷4, 011=÷8, 100=÷16. Values other than 0-4 are invalid.
            param init_val = 0x0;
            is read;
            is write;
        }
        field RESEN @ [1:1] {
            // Enable watchdog reset output (WDOGRES). Acts as a mask for the reset output. Set to 1 to enable the reset, or to 0 to disable the reset. Only affects behavior on the second timeout.
            param init_val = 0x0;
